INSERT INTO reviews (user_id, movie_id, title, body, status) SELECT u.id, m.id, 'A staggering achievement', 'The docking sequence alone justifies the runtime. Hans Zimmer''s organ score turns orbital mechanics into something close to liturgy, and the film earns its emotional swings honestly.', 'PUBLISHED' FROM users u, movies m WHERE u.email = 'nolan.fan@example.com' AND m.title = 'Interstellar' ON CONFLICT DO NOTHING;
INSERT INTO reviews (user_id, movie_id, title, body, status) SELECT u.id, m.id, 'Still the benchmark', 'Fincher''s rain-soaked city is a character in its own right. The restraint in what it chooses not to show is exactly why the ending still lands decades later.', 'PUBLISHED' FROM users u, movies m WHERE u.email = 'crime.watcher@example.com' AND m.title = 'Se7en' ON CONFLICT DO NOTHING;
INSERT INTO reviews (user_id, movie_id, title, body, status) SELECT u.id, m.id, 'Endlessly re-watchable', 'Every frame rewards attention. What impresses most is how little it explains: the world simply exists, confident that curiosity will carry you through it.', 'PUBLISHED' FROM users u, movies m WHERE u.email = 'animation.buff@example.com' AND m.title = 'Spirited Away' ON CONFLICT DO NOTHING;
INSERT INTO reviews (user_id, movie_id, title, body, status) SELECT u.id, m.id, 'Structurally perfect', 'The tonal pivot at the midpoint is one of the most controlled shifts in modern cinema. It works because the class satire is never subordinated to the thriller mechanics.', 'PUBLISHED' FROM users u, movies m WHERE u.email = 'admin@example.com' AND m.title = 'Parasite' ON CONFLICT DO NOTHING;
INSERT INTO reviews (user_id, movie_id, title, body, status) SELECT u.id, m.id, 'Quiet science fiction done right', 'A first-contact story with the patience to be about grammar and grief instead of firepower. Villeneuve trusts the audience completely.', 'PUBLISHED' FROM users u, movies m WHERE u.email = 'nolan.fan@example.com' AND m.title = 'Arrival' ON CONFLICT DO NOTHING;
